<?php
namespace App\Http\Controllers\Consumer;
use App\Http\Controllers\Controller;use App\Models\MediaAsset;use App\Models\RenterDocument;use App\Services\AuditLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\View\View;
class RenterDocumentController extends Controller { public function index(Request $r):View{return view('consumer.renter-documents.index',['documents'=>$r->user()->renterDocuments()->latest()->get()]);}public function store(Request $r,AuditLogger $audit):RedirectResponse{$d=$r->validate(['document_type'=>'required|in:ktp,sim_a,sim_c,passport','document_number'=>'required|string|max:100','expires_at'=>'nullable|date|after:today','file'=>'required|file|mimes:jpg,jpeg,png,pdf|max:8192']);$file=$r->file('file');$path=$file->store('renter-documents/'.$r->user()->id,'local');$asset=MediaAsset::create(['owner_user_id'=>$r->user()->id,'is_platform_owned'=>false,'disk'=>'local','object_key'=>$path,'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'size_bytes'=>$file->getSize(),'checksum_sha256'=>hash_file('sha256',$file->getRealPath()),'visibility'=>'private','purpose'=>'renter_document','status'=>'ready','uploaded_at'=>now()]);$doc=$r->user()->renterDocuments()->create($d+['media_asset_id'=>$asset->id,'status'=>'pending']);$audit->record('renter_document.submitted',$doc,[],['document_type'=>$doc->document_type],$r->user());return back()->with('status','Dokumen dikirim.');}public function download(Request $r,RenterDocument $document){$this->authorize('view',$document);abort_unless($document->media->visibility==='private',404);return Storage::disk($document->media->disk)->download($document->media->object_key,$document->media->original_name);} }
